const VISITS_KEY="bbmp_eplan_studio_visits_2026",PLANS_KEY="bbmp_eplan_studio_plans_2026",API_BASE="https://countapi.mileshilliard.com/api/v1";function initLiveStats(e=!1){const s="eplan_visit_session_tracked";let n=!1;if(e)try{sessionStorage.getItem(s)||(n=!0,sessionStorage.setItem(s,"true"))}catch{n=!0}const o=n?`${API_BASE}/hit/${VISITS_KEY}`:`${API_BASE}/get/${VISITS_KEY}`;fetch(o).then(t=>t.json()).then(t=>{t&&typeof t.value=="number"&&updateStatElements("statVisits",t.value)}).catch(t=>console.warn("Visits counter offline:",t)),fetch(`${API_BASE}/get/${PLANS_KEY}`).then(t=>t.json()).then(t=>{t&&typeof t.value=="number"&&updateStatElements("statPlans",t.value)}).catch(t=>console.warn("Plans counter offline:",t))}function trackPlanGenerated(){fetch(`${API_BASE}/hit/${PLANS_KEY}`).then(e=>e.json()).then(e=>{e&&typeof e.value=="number"&&updateStatElements("statPlans",e.value)}).catch(e=>console.warn("Plan increment failed:",e))}function updateStatElements(e,s){const n=document.querySelectorAll("#"+e),o=s.toLocaleString();n.forEach(t=>{t.textContent=o})}
